var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

app.MapGet("/echo", (HttpRequest request) =>
{
    var accept = request.Headers.Accept.ToString();
    var correlationId = request.Headers["X-Correlation-Id"].FirstOrDefault();
    var query = request.Query["filter"].ToString();
    return Results.Json(new { accept, correlationId, query });
});

app.Run();

app.MapPost("/customers", async (HttpRequest request, CancellationToken ct) =>
{
    var dto = await request.ReadFromJsonAsync<CreateCustomerDto>(ct);
    if (dto is null)
        return Results.BadRequest("Body must be JSON.");

    return Results.Created($"/customers/{Guid.NewGuid()}", dto);
});

record CreateCustomerDto(string Name, string Email);

app.MapGet("/reports/{id}", (string id, HttpResponse response) =>
{
    response.Headers.CacheControl = "private, max-age=60";
    response.Headers.Append("X-Request-Id", id);
    return Results.File("report.pdf", "application/pdf");
});

